/* ========================================
   LANDING PAGE CSS - DEFAULT STYLING
   ⚠️ Using generic color palette
   ======================================== */

/* === ROOT VARIABLES === */
:root {
  /* Default Professional Palette */
  --color-primary: #0066CC;
  --color-secondary: #003366;
  --color-accent: #FF6B35;
  --color-neutral: #F5F5F5;
  --color-text: #333333;

  /* Typography */
  --font-primary: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --line-height: 1.6;
  --letter-spacing: 0;

  /* Spacing */
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 2rem;
  --spacing-lg: 3rem;
  --spacing-xl: 4rem;
}

/* === BASE STYLES === */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-primary);
  line-height: var(--line-height);
  color: var(--color-text);
  background-color: #ffffff;
}

/* === SECTION LAYOUT === */
section {
  padding: var(--spacing-xl) var(--spacing-md);
  max-width: 1200px;
  margin: 0 auto;
}

/* === HERO SECTION === */
#hero {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
  color: white;
  text-align: center;
  padding: var(--spacing-xl) var(--spacing-md);
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

#hero h1 {
  font-size: 3rem;
  font-weight: 700;
  margin-bottom: var(--spacing-md);
}

/* === CTA BUTTONS === */
.cta-button {
  background-color: var(--color-accent);
  color: white;
  font-size: 1.25rem;
  padding: 1rem 2.5rem;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: transform 0.3s ease;
}

.cta-button:hover {
  transform: translateY(-2px);
}

/* === RESPONSIVE === */
@media (max-width: 768px) {
  #hero h1 { font-size: 2rem; }
  section { padding: var(--spacing-lg) var(--spacing-sm); }
}

/* ⚠️ NOTE: This is generic styling. For brand-aligned CSS with your Pantone colors,
   create a Context Profile with brand_guidelines and regenerate. */
